#include <omp.h>
#include <vector>
#include <cstddef>

using std::size_t;

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    size_t first_even = n;  // If no even value is found, return x.size().

    #pragma omp parallel for default(none) shared(x, n) reduction(min:first_even)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
        const size_t idx = static_cast<size_t>(i);
        if (x[idx] % 2 == 0) {
            if (idx < first_even) {
                first_even = idx;
            }
        }
    }

    return first_even;
}
